"use strict";const DatePart=require("./datepart");class Meridiem extends DatePart{constructor(t={}){super(t)}up(){this.date.setHours((this.date.getHours()+12)%24)}down(){this.up()}toString(){let t=this.date.getHours()>12?"pm":"am";return/\A/.test(this.token)?t.toUpperCase():t}}module.exports=Meridiem;